@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800&display=swap');
:root{--ink:#121814;--panel:#1a211c;--panel2:#222b24;--line:#364139;--muted:#8a968a;--cream:#e9e9d8;--lime:#c8f05b;--orange:#e5a84c;--red:#df6451;--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--body:Inter,system-ui,sans-serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101511;color:var(--cream);font-family:var(--body);-webkit-tap-highlight-color:transparent;touch-action:manipulation}.game-shell{width:100%;height:100dvh;min-height:500px;display:grid;grid-template-rows:66px minmax(0,1fr) 216px;background:var(--ink);overflow:hidden}.topbar{display:flex;align-items:center;padding:0 24px;border-bottom:1px solid #343d35;background:linear-gradient(180deg,#202821,#171e19);z-index:2;gap:26px}.brand{display:flex;align-items:center;gap:11px;min-width:255px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid #647149;color:var(--lime);font-size:20px;transform:rotate(45deg);background:#262e23}.brand-mark:first-letter{transform:rotate(-45deg)}.brand-kicker{display:block;color:#a6b09b;font:9px var(--mono);letter-spacing:1.55px;margin-bottom:2px}.brand strong{font:800 17px var(--display);letter-spacing:.65px}.brand strong i{font-style:normal;color:var(--lime)}.mission{height:35px;border-left:1px solid #3b443c;padding-left:22px;display:grid;grid-template-columns:9px auto;grid-template-rows:17px 14px;column-gap:9px;align-content:center;font:10px var(--mono);letter-spacing:.65px;color:#d9dfd0}.mission small{grid-column:2;font-size:8px;color:#859081;letter-spacing:1px}.live-dot{height:6px;width:6px;border-radius:50%;background:#c9ef5b;align-self:center;box-shadow:0 0 10px #b5e653}.top-actions{margin-left:auto;display:flex;gap:8px}.icon-btn{width:35px;height:35px;border:1px solid #3a443b;background:#222a23;color:#c5cfbd;font-size:15px;cursor:pointer;border-radius:3px}.icon-btn:hover{color:var(--lime);border-color:#74834d}.battlefield-wrap{position:relative;overflow:hidden;background:#777354}.battlefield-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.map-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 95px 15px #10151075,inset 0 -45px 60px #1015105c}.map-hud{position:absolute;top:17px;left:20px;right:20px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none;text-shadow:0 1px 5px #111}.sector{border-left:2px solid var(--lime);padding:2px 0 2px 9px;display:grid;gap:3px}.sector b{font:11px var(--mono);letter-spacing:1px}.sector span,.weather{font:9px var(--mono);letter-spacing:.8px;color:#d6d6c6}.weather{padding:9px 11px;background:#1a211b9c;border:1px solid #ffffff27;border-radius:2px}.weather span{color:#f2c65d;font-size:13px}.weather i{font-style:normal;color:#a6b09b;margin:0 4px}.objective-card{position:absolute;top:68px;left:20px;display:flex;gap:10px;align-items:center;background:#182019d9;border:1px solid #d5ef8557;padding:9px 13px 9px 10px;box-shadow:0 4px 14px #0004;transition:opacity .3s}.objective-card.done{opacity:0;pointer-events:none}.objective-icon{font-size:19px;color:var(--lime)}.objective-card div{display:grid;gap:3px}.objective-card b{font:9px var(--mono);letter-spacing:1px;color:var(--lime)}.objective-card span:last-child{font-size:10px;color:#e3e5d7}.toast{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#101711de;border:1px solid #bedb71;padding:11px 17px;font:10px var(--mono);letter-spacing:1px;color:#e8f4ce;opacity:0;pointer-events:none;transition:opacity .2s;white-space:nowrap;z-index:5}.toast.show{opacity:1}.start-screen,.pause-screen,.end-screen{position:absolute;inset:0;z-index:4;background:linear-gradient(90deg,#0d130fd9 0%,#111710b8 37%,#10161038 100%);display:flex;align-items:center;padding:30px 7%;transition:opacity .3s}.start-screen.hidden,.pause-screen.hidden,.end-screen.hidden{display:none}.briefing-card{width:min(380px,48%);padding:27px 28px;background:linear-gradient(135deg,#1c261fef,#131a15f2);border:1px solid #59634c;box-shadow:0 14px 45px #0008;position:relative}.briefing-card:before,.briefing-card:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--lime);border-style:solid}.briefing-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}.briefing-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.briefing-eyebrow{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1px;color:#a8b297}.briefing-eyebrow span:first-child{color:var(--lime)}.briefing-title{font:900 57px/.82 var(--display);letter-spacing:1px;margin:24px 0 18px}.briefing-title em{font-style:normal;color:var(--lime)}.briefing-card p{max-width:320px;font-size:12px;line-height:1.7;color:#b9c1b4;margin:0 0 21px}.briefing-stats{display:grid;grid-template-columns:1fr 1fr 1fr;border-top:1px solid #394239;border-bottom:1px solid #394239;padding:12px 0;margin-bottom:17px}.briefing-stats div{display:grid;gap:5px;border-right:1px solid #394239;padding-left:11px}.briefing-stats div:first-child{padding-left:0}.briefing-stats div:last-child{border:0}.briefing-stats small{font:8px var(--mono);color:#909b8b;white-space:nowrap}.briefing-stats b{font:700 11px var(--display);letter-spacing:.4px}.briefing-stats .threat{color:#e4b458}.start-btn{width:100%;height:45px;padding:0 14px;border:0;background:var(--lime);color:#151c14;display:flex;justify-content:space-between;align-items:center;font:800 14px var(--display);letter-spacing:1px;cursor:pointer}.start-btn b{font:22px var(--body);font-weight:400}.start-btn:hover{background:#d9ff76}.briefing-foot{font:8px var(--mono);letter-spacing:.8px;color:#83907f;text-align:center;margin-top:13px}.briefing-foot span{color:var(--lime);margin:0 5px}.start-art-label{position:absolute;right:5%;bottom:18%;font:10px var(--mono);letter-spacing:1.2px;text-shadow:0 1px 6px #000}.start-art-label small{display:block;margin:6px 0 0 22px;font-size:8px;color:#bdc7b2}.art-cross{color:var(--lime);font-size:18px;margin-right:8px}.pause-screen,.end-screen{background:#0d140ec9;justify-content:center}.pause-card{width:min(330px,90%);padding:30px;background:#1b241deF;border:1px solid #5b6948;text-align:center;box-shadow:0 18px 50px #0009}.pause-card>small{font:9px var(--mono);letter-spacing:1.6px;color:var(--lime)}.pause-card h2{font:900 49px var(--display);letter-spacing:2px;margin:5px 0 20px}.pause-card p{font-size:12px;color:#b6c0b3;margin:-10px 0 22px}.text-btn{background:none;border:0;color:#9da798;font:9px var(--mono);letter-spacing:1px;margin-top:15px;cursor:pointer}.command-deck{background:#171e19;border-top:1px solid #3b453b;z-index:3;display:flex;flex-direction:column}.resource-strip{height:53px;min-height:53px;border-bottom:1px solid #303a31;display:flex;align-items:center;padding:0 22px;gap:17px}.resource{display:flex;align-items:center;gap:9px;min-width:148px}.resource-icon{width:25px;height:25px;display:grid;place-items:center;border:1px solid #536044;color:var(--lime);font:500 14px var(--mono);background:#252e25}.resource-icon.power{color:#e2af50;border-color:#66563c}.resource div{display:grid;gap:1px}.resource small,.army-count small{font:8px var(--mono);color:#929d8f;letter-spacing:1px}.resource b{font:700 14px var(--display);letter-spacing:.5px;color:#eef0e2}.income{font:9px var(--mono);color:var(--lime);margin-left:-3px}.resource-divider{height:26px;border-left:1px solid #343e36;margin-right:1px}.power-bars{display:flex;gap:2px;margin-left:4px}.power-bars i{width:4px;height:13px;background:#9bd04b;display:block;transform:skew(-12deg)}.power-bars i:last-child{background:#637a41}.deck-spacer{flex:1}.army-count{display:flex;align-items:baseline;gap:5px}.army-count b{font:700 16px var(--display);color:var(--lime)}.army-count small{font-size:8px}.tiny-vehicle{font-size:16px;color:#bac2b3}.control-row{display:flex;min-height:0;flex:1;align-items:stretch;padding:13px 20px 11px;gap:17px}.selection-panel{width:185px;min-width:170px;display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid #343f35;background:#1c241e;align-self:center;height:62px}.selection-icon{width:37px;height:37px;border:1px solid #515e46;background:#283329;display:grid;place-items:center;color:var(--lime);font-size:20px}.selection-copy{min-width:0;flex:1;display:grid;gap:3px}.selection-copy small{font:8px var(--mono);letter-spacing:.7px;color:#9aa793}.selection-copy b{font:700 12px var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.health-track{height:3px;background:#485046;margin-top:2px}.health-track i{height:100%;display:block;background:var(--lime);width:100%;transition:width .2s}.command-actions{display:flex;gap:7px;align-self:center}.action-card{width:58px;height:62px;background:#202820;border:1px solid #38433a;color:#aab4a5;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;position:relative;font:8px var(--mono);letter-spacing:.4px;cursor:pointer}.action-card:hover,.action-card.selected-action{border-color:#9bb74f;color:#e4edcf;background:#283327}.action-card .action-glyph{font:19px var(--body);color:var(--lime)}.action-card kbd{position:absolute;right:4px;top:3px;color:#727e70;font:8px var(--mono);background:none}.build-actions{display:grid;grid-template-columns:repeat(3,minmax(110px,1fr));gap:7px;align-content:center;flex:1;min-width:0}.build-heading{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;margin-bottom:1px;font:9px var(--mono);letter-spacing:.85px;color:#d4dacb}.build-heading small{font-size:8px;color:#859181}.build-card{height:48px;display:flex;align-items:center;gap:8px;text-align:left;background:#202820;border:1px solid #3a453b;color:#e2e7d8;padding:4px 8px;cursor:pointer;min-width:0;position:relative}.build-card:hover:not(:disabled){border-color:#9bb74f;background:#293328}.build-card:disabled{opacity:.42;filter:grayscale(.4);cursor:not-allowed}.unit-art{width:29px;height:29px;display:grid;place-items:center;color:var(--lime);font-size:22px;background:#2c372b;border:1px solid #48573d;flex:0 0 auto}.tank-art{color:#d5b875}.scout-art{color:#a6c1ca}.build-copy{display:grid;min-width:0;gap:4px}.build-copy b{font:700 11px var(--display);letter-spacing:.35px;white-space:nowrap}.build-copy small{font:8px var(--mono);color:#94a08f;white-space:nowrap}.build-copy i{font-style:normal;color:#667361}.build-price{display:none}.mobile-hint{display:none}
@media(max-width:850px){.game-shell{grid-template-rows:55px minmax(0,1fr) 207px}.topbar{padding:0 14px;gap:12px}.brand{min-width:210px}.brand strong{font-size:15px}.brand-mark{width:30px;height:30px}.mission{padding-left:12px}.resource-strip{padding:0 14px}.control-row{padding:10px 12px;gap:10px}.selection-panel{width:155px;min-width:145px}.command-actions{gap:4px}.action-card{width:49px}.build-actions{gap:5px}.build-card{padding:4px 5px;gap:5px}.unit-art{width:26px;height:27px}.build-copy b{font-size:10px}.build-copy small{font-size:7px}}
@media(max-width:600px){.game-shell{min-height:0;height:100dvh;grid-template-rows:49px minmax(0,1fr) 190px}.topbar{padding:0 10px;gap:8px}.brand{min-width:0}.brand-mark{width:27px;height:27px;font-size:16px}.brand-kicker{font-size:7px;letter-spacing:1px}.brand strong{font-size:13px;letter-spacing:.25px}.mission{margin-left:auto;border:0;padding:0 7px 0 0;grid-template-columns:7px auto;column-gap:5px}.mission>span:nth-child(2){font-size:8px;letter-spacing:0}.mission small{font-size:7px}.top-actions{gap:5px}.icon-btn{width:29px;height:29px;font-size:13px}.map-hud{top:10px;left:11px;right:11px}.sector b{font-size:9px}.sector span,.weather{font-size:7px}.weather{padding:6px}.objective-card{top:53px;left:11px;padding:6px 9px}.objective-card b{font-size:8px}.objective-card span:last-child{font-size:9px}.objective-icon{font-size:16px}.start-screen{padding:12px;align-items:flex-end;background:linear-gradient(0deg,#0d130ff2 0%,#111710c4 48%,#10161015 100%)}.briefing-card{width:100%;max-width:390px;margin:0 auto 5px;padding:17px 19px}.briefing-title{font-size:44px;margin:14px 0 11px}.briefing-card p{font-size:10px;line-height:1.5;margin-bottom:12px}.briefing-stats{padding:8px 0;margin-bottom:11px}.briefing-stats small{font-size:7px}.briefing-stats b{font-size:10px}.start-btn{height:39px;font-size:12px}.briefing-foot{font-size:7px;margin-top:9px}.briefing-eyebrow{font-size:8px}.start-art-label{top:15%;bottom:auto;right:11px;font-size:8px}.start-art-label small{font-size:7px}.resource-strip{height:44px;min-height:44px;padding:0 11px;gap:9px}.resource{min-width:0;gap:6px}.resource-icon{width:21px;height:21px;font-size:12px}.resource small,.army-count small{font-size:7px}.resource b{font-size:12px}.income{font-size:8px}.resource-divider{height:22px}.power-bars{gap:2px;margin-left:2px}.power-bars i{height:10px;width:3px}.army-count{gap:3px}.army-count b{font-size:14px}.tiny-vehicle{font-size:13px}.control-row{padding:7px 9px 5px;display:grid;grid-template-columns:1fr auto;grid-template-rows:52px 1fr;gap:6px}.selection-panel{grid-column:1/2;width:100%;min-width:0;height:47px;padding:5px 7px;gap:7px;align-self:stretch}.selection-icon{width:30px;height:30px;font-size:16px}.selection-copy{gap:1px}.selection-copy small{font-size:7px}.selection-copy b{font-size:11px}.health-track{height:2px}.command-actions{grid-column:2/3;align-self:stretch}.action-card{width:42px;height:47px;font-size:7px}.action-card .action-glyph{font-size:16px}.build-actions{grid-column:1/-1;grid-row:2;grid-template-columns:repeat(3,1fr);gap:4px;align-content:start}.build-heading{margin-bottom:0;font-size:8px}.build-heading small{font-size:7px}.build-card{height:57px;flex-direction:column;justify-content:center;gap:1px;padding:2px;position:relative}.unit-art{width:22px;height:20px;font-size:16px}.build-copy{gap:1px;text-align:center}.build-copy b{font-size:9px}.build-copy small{font-size:6px}.build-price{display:none}.mobile-hint{display:block;position:absolute;bottom:2px;left:0;right:0;text-align:center;font:6px var(--mono);letter-spacing:.5px;color:#6e7c6d;pointer-events:none}.command-deck{position:relative}.pause-card{padding:24px}.toast{font-size:8px;padding:9px 12px}.map-vignette{box-shadow:inset 0 0 45px 8px #10151055,inset 0 -20px 30px #10151055}}
@media(max-height:500px) and (orientation:landscape){.game-shell{grid-template-rows:42px minmax(0,1fr) 145px}.topbar{padding:0 12px}.resource-strip{height:34px;min-height:34px}.control-row{padding:5px 10px}.selection-panel,.action-card{height:54px}.build-card{height:40px}.build-actions{grid-template-columns:repeat(3,minmax(85px,1fr))}.build-heading{font-size:8px}.start-screen{padding:15px 6%}.briefing-card{padding:14px 18px;width:340px}.briefing-title{font-size:38px;margin:10px 0}.briefing-card p{margin-bottom:9px}.briefing-stats{padding:7px 0;margin-bottom:9px}.briefing-foot{margin-top:7px}}

(() => {
  const canvas = document.getElementById('battlefield');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {credits:$('credits'),income:$('income'),power:$('power'),army:$('army-count'),type:$('selection-type'),name:$('selection-name'),icon:$('selection-icon'),health:$('selection-health'),toast:$('toast'),start:$('start-screen'),pause:$('pause-screen'),end:$('end-screen'),objective:$('objective-card')};
  const W=1200,H=800;
  let width=0,height=0,dpr=1,playing=false,paused=false,over=false,credits=2400,time=0,last=0,toastTimer=0,action='select',selected=null,shots=[],particles=[],shake=0;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const ownHQ={id:'own-hq',kind:'building',team:'blue',type:'Command Post',name:'FOB ANVIL',x:.16,y:.62,hp:100,max:100,size:45,range:0};
  const enemyHQ={id:'enemy-hq',kind:'building',team:'red',type:'Enemy Command',name:'HOSTILE HQ',x:.84,y:.33,hp:100,max:100,size:48,range:0};
  let units=[],enemies=[],decor=[],crates=[],nextEnemy=10,serial=0;
  const specs={infantry:{name:'Rifle Squad',type:'Infantry',icon:'♟',cost:450,hp:32,speed:45,range:118,damage:6,rate:.8,radius:8},tank:{name:'Strike Tank',type:'Armor',icon:'▰',cost:900,hp:95,speed:34,range:155,damage:17,rate:1.35,radius:13},scout:{name:'Scout Buggy',type:'Recon',icon:'◈',cost:650,hp:55,speed:63,range:110,damage:8,rate:.72,radius:11}};
  function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
  function setup(){units=[];enemies=[];shots=[];particles=[];crates=[];credits=2400;time=0;nextEnemy=10;serial=0;over=false;paused=false;action='select';selected=ownHQ;ownHQ.hp=100;enemyHQ.hp=100;
    for(let i=0;i<3;i++)addUnit('infantry',.22+i*.035,.67+(i%2)*.045,false);
    createDecor();refreshUI();}
  function createDecor(){decor=[];let seed=29481;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
    for(let i=0;i<260;i++){const x=random(),y=random();if(Math.abs(x-.16)<.1&&Math.abs(y-.62)<.11||Math.abs(x-.84)<.1&&Math.abs(y-.33)<.11)continue;decor.push({x,y,r:2+random()*11,kind:random()<.63?'bush':'rock',tone:random()});}
    for(let i=0;i<17;i++)crates.push({x:rand(.26,.75),y:rand(.18,.79),r:6,active:true});
  }
  function addUnit(kind,x,y,announce=true){const s=specs[kind];const u={id:'u'+(++serial),kind,team:'blue',name:s.name,type:s.type,icon:s.icon,x:clamp(x,.04,.96),y:clamp(y,.08,.92),hp:s.hp,max:s.hp,speed:s.speed,range:s.range,damage:s.damage,rate:s.rate,radius:s.radius,cool:rand(.1,.6),target:null,move:null};units.push(u);if(announce)toast(s.name+' DEPLOYED');refreshUI();return u}
  function spawn(kind){if(!playing||paused||over)return;const s=specs[kind];if(credits<s.cost){toast('INSUFFICIENT CREDITS');return}credits-=s.cost;addUnit(kind,.205+rand(-.025,.035),.69+rand(-.04,.05));}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
  function refreshUI(){ui.credits.textContent=Math.floor(credits).toLocaleString();ui.income.textContent='+12/s';ui.army.textContent=String(units.length).padStart(2,'0');document.querySelectorAll('.build-card').forEach(b=>b.disabled=credits<specs[b.dataset.unit].cost||!playing||paused||over);
    const s=selected;if(!s){ui.type.textContent='BATTLE GROUP';ui.name.textContent='No selection';ui.icon.textContent='⌖';ui.health.style.width='0%'}else{ui.type.textContent=s.type||'UNIT';ui.name.textContent=s.name;ui.icon.textContent=s.icon||'⌂';ui.health.style.width=(100*s.hp/s.max)+'%';ui.health.style.background=s.hp/s.max<.3?'#df6451':'#c8f05b'}
    document.querySelectorAll('.action-card').forEach(b=>b.classList.toggle('selected-action',b.dataset.action===action));}
  function pos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
  function dist(a,b){const dx=(a.x-b.x)*width,dy=(a.y-b.y)*height;return Math.hypot(dx,dy)}
  function onPointer(e){if(!playing||paused||over)return;const p=pos(e);let hit=null;
    for(const a of [...enemies,enemyHQ,...units,ownHQ].reverse()){if(dist(p,a)<(a.size||a.radius*2||14)+12){hit=a;break}}
    if(action==='move'&&selected&&selected.kind!=='building'){selected.move=p;selected.target=null;action='select';refreshUI();return}
    if(action==='attack'&&selected&&selected.kind!=='building'){if(hit&&hit.team==='red'){selected.target=hit;selected.move=null}else{selected.target=enemyHQ;selected.move=p}action='select';refreshUI();return}
    if(hit){if(hit.team==='blue'||hit===enemyHQ){selected=hit;refreshUI();if(hit.team==='red'&&selected&&selected.kind!=='building')selected.target=hit} else if(selected&&selected.kind!=='building'){selected.target=hit;selected.move=null;toast('TARGET ACQUIRED')}return}
    if(selected&&selected.kind!=='building'){selected.move=p;selected.target=null;toast('ORDERS RECEIVED')}
  }
  canvas.addEventListener('pointerdown',onPointer);
  document.querySelectorAll('.build-card').forEach(b=>b.addEventListener('click',()=>spawn(b.dataset.unit)));
  document.querySelectorAll('.action-card').forEach(b=>b.addEventListener('click',()=>{if(!playing)return;action=b.dataset.action;if(action!=='select')toast(action==='move'?'SELECT DESTINATION':'SELECT HOSTILE TARGET');refreshUI()}));
  $('start-btn').onclick=()=>{ui.start.classList.add('hidden');playing=true;last=performance.now();toast('FOOTHOLD ESTABLISHED · MOVE OUT');refreshUI()};
  $('pause-btn').onclick=()=>{if(!playing||over)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);$('pause-btn').textContent=paused?'▶':'Ⅱ';last=performance.now()};
  $('resume-btn').onclick=()=>{paused=false;ui.pause.classList.add('hidden');$('pause-btn').textContent='Ⅱ';last=performance.now()};
  $('restart-btn').onclick=$('again-btn').onclick=()=>{setup();ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.start.classList.remove('hidden');playing=false;refreshUI()};
  $('sound-btn').onclick=(e)=>{e.currentTarget.classList.toggle('muted');toast('SOUND EFFECTS '+(e.currentTarget.classList.contains('muted')?'OFF':'ON'))};
